parameters.jsCode:
// Pair this sent reply with the incoming email it answered.
// EMBED the question; carry the reply along as metadata.
// ($('Loop Over Replies').item.json) rather than from the trigger. Inside a
// batch-size-1 loop this is a single-item lineage, so no pairedItem blow-up.
const reply = $('Loop Over Replies').item.json;
const OUR_MAILBOX = ((reply.from && reply.from.emailAddress && reply.from.emailAddress.address) || '').toLowerCase();
const replyAt = new Date(reply.sentDateTime || reply.createdDateTime || 0).getTime();
const convId = reply.conversationId || '';

// Hard ceiling on how much raw HTML the regex pipeline ever touches per body.
const RAW_CAP = 65536;

const decode = s => String(s || '')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (m, n) => String.fromCharCode(parseInt(n, 16)));

const stripBanner = s => String(s || '')
  .replace(/<table\b(?:(?!<\/?table\b)[\s\S])*?External Email(?:(?!<\/?table\b)[\s\S])*?<\/table>/gi, ' ');

const cutHtml = s => {
  s = String(s || '');
  const M = [/appendonsend/i, /border-top:\s*solid/i, /gmail_quote/i, /<blockquote/i];
  let c = s.length;
  for (const rx of M) { const m = s.match(rx); if (m && m.index >= 0 && m.index < c) c = m.index; }
  const lt = s.lastIndexOf('<', c);
  if (lt >= 0) c = lt;
  return s.slice(0, c);
};

const cutText = s => {
  s = String(s || '');
  const M = [/-{2,}\s*Original Message\s*-{2,}/i, /\bOn .{0,160}\bwrote:/i, /\bFrom:\s.{0,120}\bSent:\s/i, /\bGet Outlook for /i];
  let c = s.length;
  for (const rx of M) { const m = s.match(rx); if (m && m.index >= 0 && m.index < c) c = m.index; }
  return s.slice(0, c);
};

const strip = h => cutText(
  decode(
    stripBanner(cutHtml(String(h || '').slice(0, RAW_CAP)))
      .replace(/<[^>]+>/g, ' ')
      .replace(/<\/?[a-z!][^>]*$/i, ' ')
  )
).replace(/\s+/g, ' ').trim();

const keepLinks = s => String(s || '').replace(
  /<a\b[^>]*\bhref=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi,
  (m, href, txt) => txt.replace(/<[^>]+>/g, '').trim() + ' (' + href + ')'
);

const stripL = h => cutText(
  decode(
    keepLinks(stripBanner(cutHtml(String(h || '').slice(0, RAW_CAP))))
      .replace(/<[^>]+>/g, ' ')
      .replace(/<\/?[a-z!][^>]*$/i, ' ')
  )
).replace(/\s+/g, ' ').trim();

// Display name from the Graph `from` object: { emailAddress: { name, address } }.
// Often absent, and Outlook frequently fills it with the address itself -- in
// that case treat it as no name at all rather than storing a duplicate.
const dispName = (o) => {
  const ea = (o && o.emailAddress) || {};
  const nm = String(ea.name || '').trim();
  const ad = String(ea.address || '').trim();
  if (!nm) return '';
  if (nm.toLowerCase() === ad.toLowerCase()) return '';
  return nm;
};

// Candidate questions: SAME conversation, from someone other than us, at/before
// this reply was sent. Filter on conversationId FIRST so a stray oversized
// inbox payload is discarded before any heavy work.
const inbound = $input.all()
  .filter(i => ((i.json && i.json.conversationId) || '') === convId)
  .map(i => i.json)
  .filter(m => {
    const f = ((m.from && m.from.emailAddress && m.from.emailAddress.address) || '').toLowerCase();
    const t = new Date(m.receivedDateTime || m.sentDateTime || 0).getTime();
    const auto = /^(automatic reply|auto-?reply|out of office|undeliverable|delivery status notification|delivery has failed|read:|accepted:|declined:|tentative:)/i
      .test(String(m.subject || '').trim());
    return f && f !== OUR_MAILBOX && t <= replyAt && !auto;
  })
  .sort((a, b) => new Date(b.receivedDateTime || 0) - new Date(a.receivedDateTime || 0));

// Unpaired: normalise to the SAME field set as the paired branch so that stage 2
// never has to reach back for missing keys. reply_text_np is folded into
// reply_text here (WF-1a deferred this to "Set - Pair Record (Unpaired)").
if (!convId || !inbound.length) {
  const rBodyNP = stripL((reply.body && reply.body.content));
  return [{ json: {
    paired: false,
    conversationId: convId,
    question_subject: '',
    question_from: '',
    question_received_at: '',
    text: '',
    reply_subject: reply.subject || '',
    reply_text: rBodyNP.slice(0, 8000),
    reply_sent_at: reply.sentDateTime || '',
    reply_from: OUR_MAILBOX
  } }];
}

const q = inbound[0];
const qBody = strip((q.body && q.body.content));
const rBody = stripL((reply.body && reply.body.content));

return [{ json: {
  paired: true,
  // ---- EMBEDDED TEXT = the incoming question ----
  text: qBody.slice(0, 8000),
  // ---- question metadata ----
  conversationId: convId,
  question_subject: q.subject || '',
  question_from: (q.from && q.from.emailAddress && q.from.emailAddress.address) || '',
  question_from_name: dispName(q.from),
  question_received_at: q.receivedDateTime || '',
  // ---- the ANSWER rides along as metadata ----
  reply_subject: reply.subject || '',
  reply_text: rBody.slice(0, 8000),
  reply_sent_at: reply.sentDateTime || '',
  reply_from: OUR_MAILBOX
}}];

// Unpaired items never reach the extract chain, so their reply body still
// carries the UCS signature block, NUS classification banners, and mobile-client
// footers. Apply the same deterministic post-clean that "Merge Bodies" applies
// to paired items, so the log format is identical across both branches.

const stripClientFooters = (s) =>
  String(s || '')
    .replace(/^\s*(?:get outlook for (?:ios|android)|sent from my \w+|sent via .+)\s*$/gim, '')
    .replace(/\s{2,}/g, ' ')
    .trim();

const stripReplyNoise = (s) => {
  let t = String(s || '');
  t = t.replace(/\[\s*NUS[^\]]*\]/gi, ' ');
  const sigIdx = t.search(/University Counselling Services\s*\(UCS\)\s*::/i);
  if (sigIdx !== -1) {
    t = t.slice(0, sigIdx);
  } else {
    const alt = t.search(/\bImportant:\s*This email is confidential\b/i);
    if (alt !== -1) t = t.slice(0, alt);
  }
  return t.replace(/\s{2,}/g, ' ').trim();
};

return $input.all().map(i => ({
  json: {
    ...i.json,
    text: '',
    reply_text: stripClientFooters(stripReplyNoise(i.json.reply_text)),
    // Unpaired items bypass "Merge Intent", so set the field here to keep the
    // log record shape identical across both branches.
    intent: ''
  }
}));

