parameters.jsCode:
// Normalise the extract chain's output so BOTH the success and error branches
// emit an identical shape: { output: { text, reply_text } }.
//
// The error branch (Azure content_filter, timeout, parser give-up) hands us the
// original input item with an `error` field and no parsed object. In that case
// we fall back to the regex-cleaned bodies that Pair Q -> A already produced.
//
// Position is preserved 1:1 with the input, which is what makes the downstream
// combine-by-position merge safe.

const parseLoose = (src) => {
  if (src && typeof src === 'object') return src;
  if (typeof src === 'string') {
    const s = src.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    try { return JSON.parse(s); } catch (e) { return {}; }
  }
  return {};
};

const pick = (v, fb) => {
  const s = (v == null) ? '' : String(v).trim();
  return s.length ? s : (fb == null ? '' : String(fb));
};

return $input.all().map((item) => {
  const j = item.json;

  // Success branch: chain + structured parser puts the object under `output`.
  // Some model/parser combos surface it under `text` or `response` instead.
  let src = null;
  if (j.output !== undefined) src = j.output;
  else if (j.response !== undefined) src = j.response;
  else if (j.text !== undefined && j.reply_text === undefined) src = j.text;

  const obj = parseLoose(src);

  // Error branch has no usable object -> obj is {} and every pick() falls back.
  return { json: { output: {
    text: pick(obj.text, j.text),
    reply_text: pick(obj.reply_text, j.reply_text)
  } } };
});

// Attach the LLM's cleaned bodies onto the record, then run the deterministic
// post-clean. Reads ONLY the item's own json.
//
// Items arrive from "Merge Record + Bodies" (combine-by-position), so each item
// carries BOTH the full Pair Q -> A record AND the chain output under `output`.
// There is no $('...').item reach-back anywhere in this node -- that cross-node
// pairedItem lineage is what previously forced full-run data into memory and
// crashed the task runner once the batch size grew past 1.
//
// MODE: "Run Once for All Items". $json would resolve to the FIRST item only,
// so we iterate $input.all() explicitly and return an array. Mapping 1:1
// preserves position, which the downstream "Merge Record + Intent"
// combine-by-position depends on -- never filter here.

const stripClientFooters = (s) =>
  String(s || '')
    .replace(/^\s*(?:get outlook for (?:ios|android)|sent from my \w+|sent via .+)\s*$/gim, '')
    .replace(/\s{2,}/g, ' ')
    .trim();

const stripReplyNoise = (s) => {
  let t = String(s || '');
  // Classification banners like "[NUS Restricted]", "[NUS Confidential]".
  t = t.replace(/\[\s*NUS[^\]]*\]/gi, ' ');
  // UCS signature/contact/disclaimer block: cut from the marker onward.
  const sigIdx = t.search(/University Counselling Services\s*\(UCS\)\s*::/i);
  if (sigIdx !== -1) {
    t = t.slice(0, sigIdx);
  } else {
    const alt = t.search(/\bImportant:\s*This email is confidential\b/i);
    if (alt !== -1) t = t.slice(0, alt);
  }
  return t.replace(/\s{2,}/g, ' ').trim();
};

const stripSignoff = (s) => {
  let t = String(s || '');
  const V = [
    /\bYours sincerely\b/i, /\bYours faithfully\b/i, /\bYours truly\b/i,
    /\bKind regards\b/i, /\bBest regards\b/i, /\bWarm regards\b/i,
    /\bBest wishes\b/i, /\bSincerely\b/i, /\bCheers\b/i,
    /\bThanks and Regards\b/i, /\bThank you and regards\b/i,
  ];
  let cut = t.length;
  for (const rx of V) { const m = t.match(rx); if (m && m.index >= 0 && m.index < cut) cut = m.index; }
  return t.slice(0, cut).trim();
};

const pick = (v, fb) => {
  const s = (v == null ? '' : String(v)).trim();
  return s.length ? s : (fb || '');
};

return $input.all().map((item) => {
  const j = item.json;
  const parsed = (j.output && typeof j.output === 'object') ? j.output : {};

  // Fall back to the original regex-cleaned values if a field came back empty.
  const text = pick(parsed.text, j.text);
  const reply_text = pick(parsed.reply_text, j.reply_text);

  const textClean = stripClientFooters(stripSignoff(text));
  const replyClean = stripClientFooters(stripReplyNoise(reply_text));

  // Drop the transient `output` wrapper so downstream sees a clean record.
  const { output, ...rest } = j;
  return { json: { ...rest, text: textClean, reply_text: replyClean } };
});

