parameters.jsCode:
// Attach `intent` onto the record without disturbing any other field.
//
// Paired items arrive already combined (Merge Record + Intent,
// combine-by-position): the item carries BOTH the full record AND the LLM
// output under `output.intent`. Unpaired items arrive straight from
// "If Paired" false, via Clean Unpaired Reply, with no output key.
//
// Either way we read only the item's own json -- no cross-node $('...').item
// reach-back, which is what previously forced full-run data into memory and
// crashed the task runner.
//
// MODE: "Run Once for All Items". $json would resolve to the FIRST item only,
// so we iterate $input.all() explicitly and return an array. Mapping 1:1
// preserves position -- never filter here.

const ALLOWED = [
  "appointment", "assessment_request", "service_clarification", "operational_info",
  "volunteer_internship", "staff_referral", "partnership","consult_required", "non_actionable"
];

return $input.all().map((item) => {
  const j = item.json;

  if (j.paired !== true) {
    const { output, ...rest } = j;
    return { json: { ...rest, intent: '' } };
  }

  const parsed = (j.output && typeof j.output === 'object') ? j.output : {};
  let intent = (parsed.intent == null ? '' : String(parsed.intent)).trim().toLowerCase();
  if (!ALLOWED.includes(intent)) intent = 'non_actionable';

  // Drop the transient `output` wrapper so downstream sees a clean record.
  const { output, ...rest } = j;
  return { json: { ...rest, intent } };
});

// Derive deterministic sender_role from the inbound question's sender address.
// student   -> @u.nus.edu, @u.yale-nus.edu.sg, @u.duke.nus.edu
// visitor   -> @visitor.nus.edu.sg, @partner.nus.edu.sg
// staff     -> @nus.edu.sg
// external  -> partner orgs, gmail/yahoo/outlook, anything else
// unknown   -> no usable address

const roleFor = (address) => {
  const addr = String(address || '').trim().toLowerCase();
  const at = addr.lastIndexOf('@');
  const domain = at >= 0 ? addr.slice(at + 1) : '';

  if (!domain) return 'unknown';

  if (
    domain === 'u.nus.edu' ||
    domain.endsWith('.u.nus.edu') ||
    domain === 'u.yale-nus.edu.sg' ||
    domain.endsWith('.u.yale-nus.edu.sg') ||
    domain === 'u.duke.nus.edu' ||
    domain.endsWith('.u.duke.nus.edu')
  ) {
    return 'student';
  }

  if (
    domain === 'visitor.nus.edu.sg' ||
    domain.endsWith('.visitor.nus.edu.sg') ||
    domain === 'partner.nus.edu.sg' ||
    domain.endsWith('.partner.nus.edu.sg')
  ) {
    return 'visitor';
  }

  if (
    domain === 'nus.edu.sg' ||
    domain.endsWith('.nus.edu.sg')
  ) {
    return 'staff';
  }

  return 'external';
};

return $input.all().map(i => ({
  json: {
    ...i.json,
    sender_role: roleFor(i.json.question_from)
  }
}));

// ---------- Build Embedding Batches ----------
// text-embedding-3-large accepts an array of inputs per request. We send 96 at
// a time: large enough to amortise the round-trip, small enough to stay under
// the per-request token ceiling given each input is capped at 8000 chars.
//
// Emits one item per batch: { input: [...], _rows: [...] } where _rows carries
// the FULL source record for each input. Carrying the records here (rather than
// a positional index into some other node) is what lets "Attach Embeddings"
// avoid any cross-node reach-back at all.

const BATCH = 96;

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i += BATCH) {
  const slice = items.slice(i, i + BATCH);
  out.push({
    json: {
      _rows: slice.map((it) => it.json),
      // Embed the same string WF-1a's Default Data Loader embedded:
      //   "Subject: {question_subject}\n\n{text}"
      input: slice.map((it) => {
        const j = it.json;
        const s = `Subject: ${j.question_subject || ''}\n\n${j.text || ''}`.trim();
        // OpenAI rejects empty strings. Should never happen on the paired
        // branch, but guard anyway.
        return s.length ? s : ' ';
      })
    }
  });
}

return out;

// Re-attach the embedding vectors to their source records.
//
// The OpenAI embeddings API does NOT echo our `_rows` passthrough back, so we
// read it from the request builder. The HTTP node preserves input->output item
// order 1:1, so response item N corresponds to batch N.
//
// $('Build Embedding Batches1').all() is a bulk snapshot of one node's output,
// NOT a per-item pairedItem lookup. That distinction matters: $('X').item forces
// n8n to walk the pairedItem lineage for every item, which is what previously
// pulled the whole run into memory and crashed the task runner.

const batches = $('Build Embedding Batches').all();
const responses = $input.all();

if (responses.length !== batches.length) {
  throw new Error(
    `Embedding response count (${responses.length}) != batch count (${batches.length})`
  );
}

const out = [];

for (let b = 0; b < responses.length; b++) {
  const rows = batches[b].json._rows || [];
  const data = (responses[b].json.data || [])
    .slice()
    .sort((a, x) => (a.index || 0) - (x.index || 0));

  if (data.length !== rows.length) {
    throw new Error(
      `Batch ${b}: got ${data.length} vectors for ${rows.length} inputs`
    );
  }

  for (let k = 0; k < rows.length; k++) {
    out.push({ json: { ...rows[k], embedding: data[k].embedding } });
  }
}

return out;

// Group the paired records into Azure AI Search index batches.
//
// Azure's /docs/index endpoint accepts up to 1000 documents (or 16 MB) per
// request. We use 100 to stay well clear of the size ceiling given each doc
// carries a 3072-dim vector (~24 KB as JSON floats) plus up to 16 KB of text.
//
// Emits ONE item per batch: { value: [ ...docs ] } -- exactly the request body
// the HTTP node posts.

const BATCH = 100;

// Azure document keys must be URL-safe: letters, digits, _ - =
// conversationId is base64-ish and can contain / and +, so encode it.
const safeKey = (s) =>
  Buffer.from(String(s || ''), 'utf8')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');

const items = $input.all();
const batches = [];

for (let i = 0; i < items.length; i += BATCH) {
  const value = items.slice(i, i + BATCH).map((it) => {
    const j = it.json;
    return {
      '@search.action': 'mergeOrUpload',
      id: safeKey(`${j.conversationId}|${j.reply_sent_at}`),
      conversationId: j.conversationId || '',
      question_subject: j.question_subject || '',
      question_from: j.question_from || '',
      question_received_at: j.question_received_at || null,
      text: j.text || '',
      reply_subject: j.reply_subject || '',
      reply_text: j.reply_text || '',
      // Edm.DateTimeOffset -- must be null, not '', when absent.
      reply_sent_at: j.reply_sent_at || null,
      reply_from: j.reply_from || '',
      sender_role: j.sender_role || '',
      intent: j.intent || '',
      text_vector: j.embedding || []
    };
  });
  batches.push({ json: { value } });
}

return batches;

// Azure returns HTTP 200 even when individual documents fail, and 207 on
// partial success. Surface any per-document failure rather than silently
// dropping records.
const failures = [];
let indexed = 0;
for (const item of $input.all()) {
  for (const r of (item.json.value || [])) {
    indexed++;
    if (r.status !== true) {
      failures.push({ key: r.key, code: r.statusCode, message: r.errorMessage });
    }
  }
}
if (failures.length) {
  throw new Error(`Azure AI Search rejected ${failures.length} document(s): ` +
    JSON.stringify(failures.slice(0, 5)));
}

// Indexing succeeded -- hand the paired records back to the main path so
// "Collect All Records" / "Set - Pair Record" keep seeing full records.
// Bulk snapshot (not $('X').item) to avoid pairedItem lineage walks.
return $('Attach Embeddings').all().map((it) => {
  const { embedding, ...rest } = it.json;   // drop the 3072-dim vector
  return { json: rest };
});

// Pre-clean a forwarded email's HTML BEFORE the Markdown node converts it.
// The built-in Markdown node converts everything faithfully, including the
// "- External Email -" banner and Oracle/RightNow tracking tables, which would
// otherwise become markdown noise that dilutes the LLM's signal. Here we remove
// that chrome and cap size; the Markdown node then does the actual conversion.
//
// Emits body.content (cleaned HTML) plus _fwd_html (original, for fallback).

const RAW_CAP = 65536;

const stripChrome = s => String(s || '')
  .slice(0, RAW_CAP)
  // External Email banner table
  .replace(/<table\b(?:(?!<\/?table\b)[\s\S])*?External Email(?:(?!<\/?table\b)[\s\S])*?<\/table>/gi, ' ');

// Stamp the sent reply onto the item so the forwarded pairing node never has to
// reach back for it. This node runs on exactly the same iterations as
// "Pair Q -> A (Fwd)", and its lineage to the loop is short and Agent-free, so
// $('Loop Over Replies1').item resolves reliably HERE -- which it does not once
// the Agent has been crossed.
const reply = $('Loop Over Replies').item.json;

return $input.all().map(item => {
  const j = item.json;
  const origHtml = (j.body && j.body.content) || '';
  return {
    json: {
      ...j,
      _reply: reply,                       // sent reply, carried to Pair Q -> A (Fwd)
      _fwd_html: origHtml,                 // untouched original, for fallback
      _fwd_clean_html: stripChrome(origHtml), // fed to the Markdown node
    },
    pairedItem: item.pairedItem,
  };
});

