parameters.jsCode:
// Pair a FORWARDED inbound question with the sent reply it produced.
//
// Three deliberate differences from the main "Pair Q -> A":
//
// 1. The QUESTION body is NOT HTML-stripped. "Code - Apply Query Body" has
//    already replaced body.content with the Agent's verbatim plain-text
//    extraction, so re-running strip() would only mangle punctuation and flatten
//    the paragraph breaks. We trim, cap runs of blank lines, and cap length --
//    no tag removal, no quote cutting, no entity decoding.
//    If the Agent produced nothing, "Code - Apply Query Body" restored the
//    original HTML and set _fwd_extracted=false; that case DOES get the full
//    strip(), otherwise raw markup would reach the embedding.
//
// 2. The REPLY is untouched by any of the above -- it is still raw Outlook HTML
//    straight from Sent Items, so it gets the identical stripL() treatment the
//    main node applies (links preserved as "text (href)").
//
// 3. The sent reply is read from $json._reply, stamped on by
//    "Code - Fwd Pre-clean HTML". NO $('Loop Over Replies1').item reach-back:
//    that pairedItem walk would have to cross the Agent node. .all() is not a
//    substitute either -- this node only runs on forwarded iterations, so its
//    run index does not track the loop's.
//
// Output shape is field-for-field identical to the main node, so everything
// downstream of "Loop Over Replies" done is unchanged.

const RAW_CAP = 65536;

const decode = s => String(s || '')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (m, n) => String.fromCharCode(parseInt(n, 16)));

const stripBanner = s => String(s || '')
  .replace(/<table\b(?:(?!<\/?table\b)[\s\S])*?External Email(?:(?!<\/?table\b)[\s\S])*?<\/table>/gi, ' ');

const cutHtml = s => {
  s = String(s || '');
  const M = [/appendonsend/i, /border-top:\s*solid/i, /gmail_quote/i, /<blockquote/i];
  let c = s.length;
  for (const rx of M) { const m = s.match(rx); if (m && m.index >= 0 && m.index < c) c = m.index; }
  const lt = s.lastIndexOf('<', c);
  if (lt >= 0) c = lt;
  return s.slice(0, c);
};

const cutText = s => {
  s = String(s || '');
  const M = [/-{2,}\s*Original Message\s*-{2,}/i, /\bOn .{0,160}\bwrote:/i, /\bFrom:\s.{0,120}\bSent:\s/i, /\bGet Outlook for /i];
  let c = s.length;
  for (const rx of M) { const m = s.match(rx); if (m && m.index >= 0 && m.index < c) c = m.index; }
  return s.slice(0, c);
};

// Display name from the Graph `from` object: { emailAddress: { name, address } }.
// Often absent, and Outlook frequently fills it with the address itself -- in
// that case treat it as no name at all rather than storing a duplicate.
const dispName = (o) => {
  const ea = (o && o.emailAddress) || {};
  const nm = String(ea.name || '').trim();
  const ad = String(ea.address || '').trim();
  if (!nm) return '';
  if (nm.toLowerCase() === ad.toLowerCase()) return '';
  return nm;
};

const strip = h => cutText(
  decode(
    stripBanner(cutHtml(String(h || '').slice(0, RAW_CAP)))
      .replace(/<[^>]+>/g, ' ')
      .replace(/<\/?[a-z!][^>]*$/i, ' ')
  )
).replace(/\s+/g, ' ').trim();

const keepLinks = s => String(s || '').replace(
  /<a\b[^>]*\bhref=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi,
  (m, href, txt) => txt.replace(/<[^>]+>/g, '').trim() + ' (' + href + ')'
);

const stripL = h => cutText(
  decode(
    keepLinks(stripBanner(cutHtml(String(h || '').slice(0, RAW_CAP))))
      .replace(/<[^>]+>/g, ' ')
      .replace(/<\/?[a-z!][^>]*$/i, ' ')
  )
).replace(/\s+/g, ' ').trim();

// Plain-text passthrough: no tag stripping. Normalise trailing spaces and
// collapse 3+ blank lines so paragraph structure survives into the embedding.
const passthrough = s => String(s || '')
  .slice(0, RAW_CAP)
  .replace(/[ \t]+$/gm, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const items = $input.all();
const q = items.length ? items[0].json : {};

// The sent reply is read from a BULK SNAPSHOT of "Code - Fwd Pre-clean HTML",
// which stamped it on before the Markdown node. Two reasons this and not
// $('Loop Over Replies').item:
//
//   * n8n's Markdown node returns via helpers.returnJsonArray(), which does NOT
//     attach pairedItem. Any .item walk from here backwards dies at that node --
//     that is what broke the original forwarded path.
//   * .all()/.first() need no lineage, and "Code - Fwd Pre-clean HTML" executes
//     on exactly the same iterations as this node, so their run indices agree.
//     (A snapshot of a node that runs EVERY iteration -- e.g. Loop Over Replies
//     itself -- would NOT be safe here, since this node only runs on forwarded
//     ones and its run index would lag.)
//
// q._reply is preferred when it survived the Agent hop; the snapshot is the
// authoritative fallback.
const snap = $('Code - Fwd Pre-clean HTML').first().json || {};
const reply = (q._reply && q._reply.conversationId) ? q._reply : (snap._reply || {});

const OUR_MAILBOX = ((reply.from && reply.from.emailAddress && reply.from.emailAddress.address) || '').toLowerCase();
const replyAt = new Date(reply.sentDateTime || reply.createdDateTime || 0).getTime();
const convId = reply.conversationId || '';

const rBody = stripL((reply.body && reply.body.content));

// Same guards as the main node: same conversation, not us, at/before the reply,
// not an auto-reply. Upstream filters already enforce these; kept so a forwarded
// item that slips through degrades to unpaired rather than mispairing.
const qFrom = ((q.from && q.from.emailAddress && q.from.emailAddress.address) || '').toLowerCase();
const qAt = new Date(q.receivedDateTime || q.sentDateTime || 0).getTime();
const qAuto = /^(automatic reply|auto-?reply|out of office|undeliverable|delivery status notification|delivery has failed|read:|accepted:|declined:|tentative:)/i
  .test(String(q.subject || '').trim());

const usable = convId
  && ((q.conversationId || '') === convId)
  && qFrom
  && qFrom !== OUR_MAILBOX
  && qAt <= replyAt
  && !qAuto;

if (!usable) {
  return [{ json: {
    paired: false,
    conversationId: convId,
    question_subject: '',
    question_from: '',
    question_received_at: '',
    text: '',
    reply_subject: reply.subject || '',
    reply_text: rBody.slice(0, 8000),
    reply_sent_at: reply.sentDateTime || '',
    reply_from: OUR_MAILBOX
  } }];
}

const raw = (q.body && q.body.content) || '';
// _fwd_extracted true  -> Agent gave us clean text, pass it through untouched.
// _fwd_extracted false -> original HTML was restored upstream, so strip it.
const qBody = q._fwd_extracted === true ? passthrough(raw) : strip(raw);

return [{ json: {
  paired: true,
  // ---- EMBEDDED TEXT = the forwarded covering message ----
  text: qBody.slice(0, 8000),
  // ---- question metadata ----
  conversationId: convId,
  question_subject: q.subject || '',
  question_from: qFrom,
  question_from_name: dispName(q.from),
  question_received_at: q.receivedDateTime || '',
  // ---- the ANSWER rides along as metadata ----
  reply_subject: reply.subject || '',
  reply_text: rBody.slice(0, 8000),
  reply_sent_at: reply.sentDateTime || '',
  reply_from: OUR_MAILBOX
}}];

// Replaces "Check Index Result". The vector store node throws on batch
// failure, so reaching this node means the insert succeeded.
//
// Restore the full paired records for the main path 

return $('If Paired (Index)').all(0).map((it) => ({ json: it.json }));

// Pre-clean a forwarded email's HTML BEFORE the Markdown node converts it.
// The built-in Markdown node converts everything faithfully, including the
// "- External Email -" banner and Oracle/RightNow tracking tables, which would
// otherwise become markdown noise that dilutes the LLM's signal. Here we remove
// that chrome and cap size; the Markdown node then does the actual conversion.
//
// Emits body.content (cleaned HTML) plus _fwd_html (original, for fallback).

const RAW_CAP = 65536;

const stripChrome = s => String(s || '')
  .slice(0, RAW_CAP)
  // External Email banner table
  .replace(/<table\b(?:(?!<\/?table\b)[\s\S])*?External Email(?:(?!<\/?table\b)[\s\S])*?<\/table>/gi, ' ')
  // style/script/comments
  .replace(/<style\b[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script\b[\s\S]*?<\/script>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  // tracking pixels / template images with no alt
  .replace(/<img\b(?![^>]*\balt=)[^>]*>/gi, ' ');

// Stamp the sent reply onto the item so the forwarded pairing node never has to
// reach back for it. This node runs on exactly the same iterations as
// "Pair Q -> A (Fwd)", and its lineage to the loop is short and Agent-free, so
// $('Loop Over Replies1').item resolves reliably HERE -- which it does not once
// the Agent has been crossed.
const reply = $('Loop Over Replies').item.json;

return $input.all().map(item => {
  const j = item.json;
  const origHtml = (j.body && j.body.content) || '';
  return {
    json: {
      ...j,
      _reply: reply,                       // sent reply, carried to Pair Q -> A (Fwd)
      _fwd_html: origHtml,                 // untouched original, for fallback
      _fwd_clean_html: stripChrome(origHtml), // fed to the Markdown node
    },
    pairedItem: item.pairedItem,
  };
});

// Build mergeOrUpload batches stamping the typed top-level reply_sent_at field
// onto documents the vector store node wrote without it.
//
// Pagination means $input.all() holds ONE ITEM PER PAGE, not one per document,
// so flatten across pages before batching.

const docs = [];
for (const p of $input.all()) {
  const body = (p.json && p.json.body) || p.json || {};
  for (const d of (body.value || [])) docs.push(d);
}

const BATCH = 500; // Azure caps an index batch at 1000 docs / 16 MB
const out = [];
let batch = [];

for (const d of docs) {
  const attrs = (d.metadata && d.metadata.attributes) || [];
  const hit = attrs.find((a) => a.key === 'reply_sent_at');
  const val = hit && hit.value ? String(hit.value).trim() : '';

  // No usable timestamp: leave the field null rather than fail the batch.
  if (!val || !d.id) continue;

  batch.push({ '@search.action': 'mergeOrUpload', id: d.id, reply_sent_at: val });

  if (batch.length >= BATCH) {
    out.push({ json: { value: batch, batch_size: batch.length } });
    batch = [];
  }
}
if (batch.length) out.push({ json: { value: batch, batch_size: batch.length } });

return out;

