parameters.jsCode:
// Lift the consult gate's boolean onto the record and drop the LLM wrapper.
//
// Items arrive from "Merge Record + Consult" (combine-by-position): each item
// carries BOTH the full record AND the chain output under `output`. Reads only
// the item's own json -- no cross-node $('...').item reach-back, matching the
// pattern used by "Merge Bodies" and "Merge Intent".
//
// MODE: "Run Once for All Items". Mapping is strictly 1:1 -- never filter here,
// or the downstream combine-by-position merge will misalign.

return $input.all().map((item) => {
  const j = item.json;
  const parsed = (j.output && typeof j.output === 'object') ? j.output : {};

  let flag = parsed.consult_required;
  if (typeof flag === 'string') flag = flag.trim().toLowerCase() === 'true';
  flag = flag === true;

  const { output, ...rest } = j;
  return { json: { ...rest, consult_required: flag } };
});

