parameters.jsCode:
// Resolve the clinician(s) this message refers to, if any.
//
// Items arrive from "Merge Record + Clinician" (combine-by-position): each
// item carries BOTH the full record AND the chain output under `output`.
// Reads only the item's own json -- no cross-node $('...').item reach-back,
// matching "Merge Bodies" and "Apply Consult".
//
// NOTE: reads only the QUESTION-derived names. reply_text is never consulted
// here -- for backfill rows the reply IS the forward, so using it would leak
// the label the consult gate is trying to predict.
//
// MODE: "Run Once for All Items". Mapping is strictly 1:1 -- never filter here,
// or the downstream combine-by-position merge will misalign.
//
// There is no clinician roster, so every extracted name is passed through --
// all of them when several survive, comma-separated. This node no longer
// decides WHICH name is the clinician; it only removes the sender's own name
// and hands the rest to the gate. Consequence: names that are not clinicians
// (a professor, a parent, a friend, or the student named in third-party mail)
// will populate this field, so ASSIGNED_CLINICIAN is a weaker signal than its
// name suggests and the gate prompt should treat it as "a person is named
// here", not "a clinician is assigned".
//
// The distinct values this node emits ARE a roster draft: names recurring
// across many senders are clinicians, one-offs are everyone else.

const TITLE_RE = /^\s*(?:ms|mrs|mr|dr|miss|prof|professor)\.?\s+/i;

const norm = (s) => String(s || '')
  .toLowerCase()
  .replace(TITLE_RE, '')
  .replace(/[^a-z\s'-]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Name tokens recoverable from the sender's address. ~39% of senders use a
// matric-style local part (e1518424@u.nus.edu) and yield nothing -- for those
// this guard simply does not fire, which is why it is a filter and not a test.
// The extraction prompt is the primary self-name defence; this is a backstop.
const senderTokens = (from) => {
  const local = String(from || '').toLowerCase().split('@')[0] || '';
  return new Set(
    local.split(/[._\-+]/).filter((t) => t.length > 2 && !/^\d+$/.test(t))
  );
};

return $input.all().map((item) => {
  const j = item.json;
  const parsed = (j.output && typeof j.output === 'object') ? j.output : {};
  const names = Array.isArray(parsed.mentioned_names) ? parsed.mentioned_names : [];

  const mine = senderTokens(j.question_from);

  // Drop anything that is really the sender writing their own name.
  const isSelf = (raw) => {
    const parts = norm(raw).split(' ').filter(Boolean);
    return parts.length > 0 && parts.every((p) => mine.has(p));
  };

  const seen = new Set();
  const candidates = [];
  for (const raw of names) {
    const clean = String(raw || '').trim();
    const key = norm(clean);
    if (!key) continue;          // punctuation-only or empty
    if (isSelf(clean)) continue; // the sender naming themselves
    if (seen.has(key)) continue; // "Ms Lim" and "Lim" normalise alike
    seen.add(key);
    candidates.push(clean);
  }

  const { output, ...rest } = j;
  return { json: { ...rest, assigned_clinician: candidates.length ? candidates.join(', ') : 'none' } };
});
